import{_ as t,c as e,o as a,a4 as n}from"./chunks/framework.ttppV29E.js";const o="/assets/input-full-dialog.DlbcWOt6.png",_=JSON.parse('{"title":"Endpoint Input","description":"","frontmatter":{},"headers":[],"relativePath":"docs/endpoint-input/input.md","filePath":"docs/endpoint-input/input.md","lastUpdated":1791278387000}'),i={name:"docs/endpoint-input/input.md"},s=n('<h1 id="endpoint-input" tabindex="-1">Endpoint Input <a class="header-anchor" href="#endpoint-input" aria-label="Permalink to &quot;Endpoint Input&quot;">​</a></h1><p>The example input in the input dialog defines the data available for preview and validation throughout the endpoint editor.</p><p>A schema, typically generated automatically from the example input, is used to validate input when the endpoint runs. For most formats, you can also edit the schema directly.</p><p><img src="'+o+'" alt="Input dialog"></p><p>When the endpoint runs, if the input does not meet the schema requirements the endpoint returns a 400 status code and halts further processing.</p><p>The input dialog also supports <a href="/docs/endpoint-input/aireblocks-integrations.html">AireBlocks integrations</a>.</p><h2 id="stream-input" tabindex="-1">Stream Input <a class="header-anchor" href="#stream-input" aria-label="Permalink to &quot;Stream Input&quot;">​</a></h2><p>Setting the input format to <code>Stream</code> lets an endpoint accept raw binary data (a file upload, for example) instead of a structured document like JSON or XML. There&#39;s no structure to validate, so example input and a schema aren&#39;t available for this format - the dialog shows an <code>Input and schema are unavailable for the selected format</code> notice instead.</p><p>A <code>Stream</code> input isn&#39;t intended to be mapped field-by-field like other formats. Instead it&#39;s forwarded on to a later task - typically an <a href="/docs/endpoints/http-request.html#stream-input">HTTP Request</a> or <a href="/docs/endpoints/aireglu-endpoint-request.html">AireGlu Endpoint Request</a> task - which sends it on as-is. See those pages for how to reference it.</p>',9),r=[s];function p(d,l,u,c,h,m){return a(),e("div",null,r)}const g=t(i,[["render",p]]);export{_ as __pageData,g as default};
